CREATE DATABASE IF NOT EXISTS myblog CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE myblog;
CREATE TABLE users (id INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(30) NOT NULL UNIQUE, email VARCHAR(120) UNIQUE, phone VARCHAR(30) UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('user','author','admin') NOT NULL DEFAULT 'user', status ENUM('active','disabled') NOT NULL DEFAULT 'active', avatar_url VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE articles (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, summary TEXT, content LONGTEXT NOT NULL, author_id INT NOT NULL, category_id INT, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', published_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (author_id) REFERENCES users(id), FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL, INDEX idx_articles_status_date(status,published_at));
CREATE TABLE drafts (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200) NOT NULL DEFAULT '', summary TEXT, content LONGTEXT, author_id INT NOT NULL, category_id INT, status ENUM('draft','published') NOT NULL DEFAULT 'draft', risk_info JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE tags (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE article_tags (article_id INT NOT NULL, tag_id INT NOT NULL, PRIMARY KEY(article_id,tag_id), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE);
CREATE TABLE messages (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT, content VARCHAR(200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE replies (id INT PRIMARY KEY AUTO_INCREMENT, message_id INT NOT NULL, user_id INT, content VARCHAR(200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE private_contents (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200), content LONGTEXT NOT NULL, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE personal_profile (id INT PRIMARY KEY AUTO_INCREMENT, bio TEXT, skills JSON, projects JSON, contact JSON, avatar_url VARCHAR(500));
CREATE TABLE personal_timeline (id INT PRIMARY KEY AUTO_INCREMENT, event_date DATE, title VARCHAR(200), content TEXT);
CREATE TABLE personal_interests (id INT PRIMARY KEY AUTO_INCREMENT, category VARCHAR(50), title VARCHAR(200), summary TEXT, link VARCHAR(500));
CREATE TABLE friend_links (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100), description TEXT, url VARCHAR(500) NOT NULL);
CREATE TABLE reading_data (id BIGINT PRIMARY KEY AUTO_INCREMENT, article_id INT NOT NULL, user_id INT, duration_seconds INT DEFAULT 0, scroll_depth TINYINT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE);
CREATE TABLE reading_heatmap_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, article_id INT NOT NULL, section_key VARCHAR(100), dwell_seconds INT DEFAULT 0, recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE);
CREATE TABLE password_reset_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, token_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE login_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id INT, ip_address VARCHAR(64), success BOOLEAN, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
